using System;using System.Collections;using System.Collections.Generic;using System.IO;using System.Reflection;using NUnit.Framework;using Rootborn.Game.Common;using Rootborn.Game.Save;using Rootborn.Game.StudentLife;using Rootborn.UI.StudentLife;using UnityEngine;using Object=UnityEngine.Object;
namespace Rootborn.Tests.EditMode.UI.StudentLife{
public sealed class DailyEventLocationQueueTests{
readonly List<Object> owned=new List<Object>();string oldRoot;GameObject canvas,player,point,runnerGo;LocationIdentityPanel locationPanel;DailyEventPanel eventPanel;object runner;Type runnerType;DailyEventDefinition definition;
T Keep<T>(T o)where T:Object{owned.Add(o);return o;}
[SetUp]public void Setup(){SaveService.SetRootDirectoryForTests(Path.Combine(Application.temporaryCachePath,"event-queue",Guid.NewGuid().ToString("N")));canvas=Keep(new GameObject("QueueCanvas",typeof(RectTransform),typeof(Canvas)));locationPanel=LocationIdentityPanel.EnsureInScene(canvas.GetComponent<Canvas>());eventPanel=DailyEventPanel.EnsureInScene(canvas.GetComponent<Canvas>());player=Keep(new GameObject("QueuePlayer",typeof(StudentLifeProgressComponent),typeof(DailyEventProgressComponent)));player.GetComponent<StudentLifeProgressComponent>().ConfigureForTests("queue-slot","queue-player",100,100,0,480);point=Keep(new GameObject("QueueLocation",typeof(LocationActivityInteractor)));var location=Keep(ScriptableObject.CreateInstance<LocationDefinition>());location.ConfigureForTests("queue-location","Queue location",Vector2.zero,Array.Empty<DiscoveryDefinition>());var identity=Keep(ScriptableObject.CreateInstance<LocationIdentityDefinition>());identity.ConfigureForTests("queue-identity","Queue identity",location,"Description",Array.Empty<LocationActivityDefinition>(),Array.Empty<LocationHintEntry>(),480,1140);point.GetComponent<LocationActivityInteractor>().Bind(identity);definition=Keep(ScriptableObject.CreateInstance<DailyEventDefinition>());definition.ConfigureForTests("queue-event","Queued event","An authored event",location,null,null,Array.Empty<DailyEventAvailabilityRuleBase>(),Array.Empty<DailyEventChoiceDefinition>());runnerType=typeof(DailyEventRuntimeInstaller).GetNestedType("Runner",BindingFlags.NonPublic);runnerGo=Keep(new GameObject("QueueRunner"));runner=runnerGo.AddComponent(runnerType);Set("_panel",eventPanel);Set("_resolver",new DailyEventResolver(new[]{definition}));}
[TearDown]public void Cleanup(){foreach(var o in owned)if(o!=null)Object.DestroyImmediate(o);owned.Clear();SaveService.SetRootDirectoryForTests(null);}
void Set(string key,object value)=>runnerType.GetField(key,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(runner,value);
IEnumerator Begin(){var m=runnerType.GetMethod("PresentAfterLocationChoice",BindingFlags.Instance|BindingFlags.NonPublic);Assert.That(m,Is.Not.Null,"Location interaction must queue the event until its primary choice modal closes, regardless of subscriber order");return (IEnumerator)m.Invoke(runner,new object[]{point.GetComponent<LocationActivityInteractor>(),player});}
[Test]public void EventWaitsForLocationChoiceThenOpensWithoutLosingAuthoredContent(){var work=Begin();Assert.That(work.MoveNext(),Is.True,"First yield lets all location interaction listeners finish");locationPanel.Show(point.GetComponent<LocationActivityInteractor>().Identity,player);for(int i=0;i<3;i++){Assert.That(work.MoveNext(),Is.True);Assert.That(eventPanel.IsOpen,Is.False,"Never hide a legitimate event behind the primary location modal");}locationPanel.Hide();Assert.That(work.MoveNext(),Is.False);Assert.That(eventPanel.IsOpen,Is.True);Assert.That(eventPanel.transform.Find("DailyEventRoot/DailyEventTitle").GetComponent<UnityEngine.UI.Text>().text,Does.Contain("Queued event"));}
[Test]public void DestroyedInteractionOwnerCancelsPendingEvent(){var work=Begin();Assert.That(work.MoveNext(),Is.True);locationPanel.Show(null,player);Object.DestroyImmediate(point);locationPanel.Hide();Assert.That(work.MoveNext(),Is.False);Assert.That(eventPanel.IsOpen,Is.False);}
}}
